import{_ as s,o as a,c as i,ag as e}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"Configuration Overview","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/index.md","filePath":"configuration/index.md","lastUpdated":1772297611000}'),n={name:"configuration/index.md"};function o(r,t,l,h,p,d){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="configuration-overview" tabindex="-1">Configuration Overview <a class="header-anchor" href="#configuration-overview" aria-label="Permalink to &quot;Configuration Overview&quot;">​</a></h1><p>NectoProxy provides a flexible, layered configuration system that lets you control every aspect of the proxy at startup and during runtime. Whether you prefer CLI flags, the REST API, or the graphical Settings panel, you can tune NectoProxy to fit your workflow.</p><h2 id="configuration-methods" tabindex="-1">Configuration Methods <a class="header-anchor" href="#configuration-methods" aria-label="Permalink to &quot;Configuration Methods&quot;">​</a></h2><p>NectoProxy can be configured through three complementary mechanisms:</p><h3 id="_1-cli-flags-startup" tabindex="-1">1. CLI Flags (Startup) <a class="header-anchor" href="#_1-cli-flags-startup" aria-label="Permalink to &quot;1. CLI Flags (Startup)&quot;">​</a></h3><p>When you launch NectoProxy from the terminal, you can pass command-line flags to override default values. These flags take effect immediately when the proxy starts.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start with custom ports and host binding</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9999</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9998</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start without auto-opening the browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span></code></pre></div><p>CLI flags are ideal for one-off configurations or scripted environments where you need deterministic startup behavior.</p><h3 id="_2-settings-api-runtime" tabindex="-1">2. Settings API (Runtime) <a class="header-anchor" href="#_2-settings-api-runtime" aria-label="Permalink to &quot;2. Settings API (Runtime)&quot;">​</a></h3><p>NectoProxy exposes a RESTful Settings API on the Web UI port. You can read and update settings programmatically while the proxy is running.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Read all settings</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Update a specific setting</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings/proxyPort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;value&quot;: 9999}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Update multiple settings at once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;proxyPort&quot;: 9999, &quot;requestTimeout&quot;: 60000}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reset all settings to defaults</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings/reset</span></span></code></pre></div><h3 id="_3-web-ui-settings-panel" tabindex="-1">3. Web UI Settings Panel <a class="header-anchor" href="#_3-web-ui-settings-panel" aria-label="Permalink to &quot;3. Web UI Settings Panel&quot;">​</a></h3><p>The most convenient way to configure NectoProxy is through the Settings panel in the Web UI. Click the <strong>gear icon</strong> in the header toolbar to open the Settings dialog. Changes are saved to the database and persist across restarts.</p><p>The Settings panel provides controls for:</p><ul><li>Proxy port and UI port</li><li>Request timeout and max body size</li><li>Auto-record and auto-open browser behavior</li><li>Breakpoint timeout</li><li>Theme selection (Dark / Light / System)</li><li>Upstream proxy configuration</li><li>SSL passthrough domains</li><li>Mobile device configuration with QR codes</li></ul><h2 id="data-directory" tabindex="-1">Data Directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data Directory&quot;">​</a></h2><p>NectoProxy stores all persistent data in a single directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.nectoproxy/</span></span></code></pre></div><p>This directory is created automatically on first launch and contains:</p><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>~/.nectoproxy/data.db</code></td><td>SQLite database (sessions, traffic, rules, settings, etc.)</td></tr><tr><td><code>~/.nectoproxy/certs/</code></td><td>Generated CA and domain certificates</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The data directory path resolves to your home directory. On Linux and macOS this is typically <code>/home/username/.nectoproxy/</code> or <code>/Users/username/.nectoproxy/</code>. On Windows it is <code>C:\\Users\\username\\.nectoproxy\\</code>.</p></div><h2 id="configuration-priority" tabindex="-1">Configuration Priority <a class="header-anchor" href="#configuration-priority" aria-label="Permalink to &quot;Configuration Priority&quot;">​</a></h2><p>When the same setting is specified through multiple methods, NectoProxy follows this priority order (highest to lowest):</p><ol><li><strong>CLI flags</strong> -- Applied at startup, override everything else for that launch session.</li><li><strong>Settings API / Web UI changes</strong> -- Persisted to the database, take effect immediately.</li><li><strong>Database defaults</strong> -- If no value has been explicitly set, NectoProxy uses built-in defaults.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>CLI flags such as <code>--port</code> and <code>--host</code> only affect the current process launch. They do not permanently modify the stored settings. If you want a permanent change, update the setting through the Web UI or the Settings API.</p></div><h2 id="configuration-sub-pages" tabindex="-1">Configuration Sub-Pages <a class="header-anchor" href="#configuration-sub-pages" aria-label="Permalink to &quot;Configuration Sub-Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What It Covers</th></tr></thead><tbody><tr><td><a href="./proxy-settings.html">Proxy Settings</a></td><td>Ports, host binding, timeouts, body size limits, recording, and breakpoint behavior</td></tr><tr><td><a href="./ui-settings.html">UI Settings</a></td><td>Theme selection, dark/light mode toggle</td></tr><tr><td><a href="./storage.html">Storage &amp; Database</a></td><td>SQLite database, certificate storage, backups, and migration</td></tr></tbody></table>`,27)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
